CREATE TABLE x1(a TEXT,b INTEGER CHECK(b>0)); CREATE TABLE t1(a TEXT,b INTEGER,CHECK(b>0)); INSERT INTO x1 VALUES('x','xx'),('y','yy'); INSERT INTO t1 SELECT * FROM x1; CREATE TABLE x2(a CHECK(a||b),b); CREATE TABLE t2(a,b,CHECK(a||b)); INSERT INTO x2 VALUES(1,'xx'),(1,'yy'); INSERT INTO t2 SELECT * FROM x2;